package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.content.pm.*;import android.database.Cursor;import android.media.AudioManager;import android.net.Uri;import android.os.*;import android.speech.tts.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,shadows={SpeechServiceTest.ManualTts.class}) @LooperMode(LooperMode.Mode.PAUSED)
public class SpeechPrefetchTest {
 static File book;Application app;ServiceController<ReadAloudService> controller;String first="Primeiro capítulo para ouvir.",third;boolean continuous=true;ReadAloudService service;final Uri uri=Uri.parse("content://seeky.prefetch.test/book.epub");
 public static class Source extends ContentProvider {public boolean onCreate(){return true;}public String getType(Uri u){return "application/epub+zip";}public ParcelFileDescriptor openFile(Uri u,String mode)throws FileNotFoundException{return ParcelFileDescriptor.open(book,ParcelFileDescriptor.MODE_READ_ONLY);}public Cursor query(Uri u,String[] p,String s,String[] a,String o){return null;}public Uri insert(Uri u,ContentValues v){return null;}public int update(Uri u,ContentValues v,String s,String[] a){return 0;}public int delete(Uri u,String s,String[] a){return 0;}}
 @Before public void setup()throws Exception{app=RuntimeEnvironment.getApplication();book=new File(app.getCacheDir(),"prefetch.epub");Source source=new Source();ProviderInfo pi=new ProviderInfo();pi.authority=uri.getAuthority();source.attachInfo(app,pi);ShadowContentResolver.registerProviderInternal(pi.authority,source);Voice local=new Voice("pt-local",new Locale("pt","PT"),400,200,false,Collections.emptySet());ShadowTextToSpeech.addVoice(local);new SpeechProfile("com.google.android.tts",local.getName(),"pt",false,1).save(app.getSharedPreferences("seeky",0));}
 void entry(ZipOutputStream zip,String name,String value)throws Exception{zip.putNextEntry(new ZipEntry(name));zip.write(value.getBytes("UTF-8"));zip.closeEntry();}
 void start(String second)throws Exception{try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(book))){entry(zip,"META-INF/container.xml","<container><rootfiles><rootfile full-path='book.opf'/></rootfiles></container>");entry(zip,"book.opf","<package><manifest><item id='a' href='a.html' media-type='application/xhtml+xml'/><item id='b' href='b.html' media-type='application/xhtml+xml'/>"+(third==null?"":"<item id='c' href='c.html' media-type='application/xhtml+xml'/>")+"</manifest><spine><itemref idref='a'/><itemref idref='b'/>"+(third==null?"":"<itemref idref='c'/>")+"</spine></package>");entry(zip,"a.html","<html><body><p>"+first+"</p></body></html>");entry(zip,"b.html","<html><body><p>"+second+"</p></body></html>");if(third!=null)entry(zip,"c.html","<html><body><p>"+third+"</p></body></html>");}controller=Robolectric.buildService(ReadAloudService.class).create();service=controller.get();shadowOf(service.audio).setNextFocusRequestResponse(AudioManager.AUDIOFOCUS_REQUEST_GRANTED);service.onStartCommand(new Intent().setAction(ReadAloudService.START).setDataAndType(uri,"application/epub+zip").putExtra("name","book.epub").putExtra("continuous",continuous),0,1);drain();SpeechServiceTest.ready(service);}
 void drain()throws Exception{for(int i=0;i<3;i++){service.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}}
 @After public void close(){if(controller!=null)controller.destroy();}
 @Test public void nextChapterIsPreparedWithoutMovingTheCurrentReadingPosition()throws Exception{start("Segundo capítulo preparado.");assertEquals(0,service.part);assertEquals(2,service.total);ReadAloudService.Prefetched next=service.worker.submit(()->service.prefetched).get(10,TimeUnit.SECONDS);assertNotNull(next);assertEquals(1,next.part);assertTrue(next.value.contains("Segundo capítulo"));assertTrue(service.cursor.pending.text.contains("Primeiro capítulo"));service.nextPart();drain();assertEquals(1,service.part);assertTrue(shadowOf(service.tts).getLastSpokenText().contains("Segundo capítulo"));}
 @Test public void editedNotebookInvalidatesPreparedChapterInsteadOfReadingStaleText()throws Exception{start("Segundo capítulo original.");ReadAloudService.Prefetched next=service.worker.submit(()->service.prefetched).get(10,TimeUnit.SECONDS);assertNotNull(next);try(ReaderStore notes=new ReaderStore(app)){notes.save(uri.toString(),1,next.value,new StudyText("Texto actualizado pelo estudante."));}service.nextPart();drain();assertTrue(shadowOf(service.tts).getLastSpokenText().contains("Texto actualizado"));assertFalse(shadowOf(service.tts).getLastSpokenText().contains("original"));}
 @Test public void largeChaptersAreNotRetainedInTheReadAheadCache()throws Exception{StringBuilder text=new StringBuilder();for(int i=0;i<5000;i++)text.append("Uma frase suficientemente longa. ");start(text.toString());assertNull(service.worker.submit(()->service.prefetched).get(10,TimeUnit.SECONDS));assertEquals(0,service.part);assertTrue(service.cursor.pending.text.contains("Primeiro"));} @Test public void timeSkipCanCrossChapterBoundaryWhileRemainingPaused()throws Exception{StringBuilder text=new StringBuilder();for(int i=0;i<250;i++)text.append("Uma frase longa para ouvir neste capítulo. ");start(text.toString());service.pause("Pausado");service.seekSeconds(30);drain();assertEquals(1,service.part);assertTrue(service.cursor.offset>0);assertTrue(service.cursor.paused);service.seekSeconds(-30);drain();assertEquals(0,service.part);assertTrue(service.cursor.paused);service.part=1;service.previousPart();drain();assertEquals(0,service.part);assertTrue(service.cursor.paused);}

}
